\begin{aligned}
\p(X > s + t \mid X > s)
&= \frac{\p(X > s + t \text{ and } X > s)}{\p(X > s)}
&& \text{Def of conditional prob.} \\
&= \frac{\p(X > s + t )}{\p(X > s)}
&& \text{Because }X > s + t\text{ implies }X > s\\
&= \frac{1 - F_X(s + t )}{1 - F_X(s)}
&& \text{Def of CDF} \\
&= \frac{e^{-\lambda (s + t)}}{e^{-\lambda s}}
&& \text{By CDF of Exp} \\
&= e^{-\lambda t}
&& \text{Simplify} \\
&= 1 - F_X(t)
&& \text{By CDF of Exp} \\
&= \p(X > t)
&& \text{Def of CDF}
\end{aligned}
